(()=>{
 const root=document.querySelector('[data-lab]');if(!root)return;const kind=root.dataset.lab;
 const text=(x,y,t,a='start')=>`<text x="${x}" y="${y}" text-anchor="${a}">${t}</text>`;
 const line=(d,on=false,dashed=false)=>`<path d="${d}" fill="none" stroke="${on?'var(--primary)':'var(--foreground)'}" stroke-width="${on?2.2:1.5}"${dashed?' stroke-dasharray="4 3"':''}/>`;
 const box=(x,y,w,h,on=false)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${on?'var(--accent)':'none'}" stroke="${on?'var(--primary)':'var(--border)'}" stroke-width="1.5"/>`;
 const bubble=(x,y)=>`<circle cx="${x}" cy="${y}" r="4" fill="var(--background)" stroke="var(--foreground)" stroke-width="1.5"/>`;
 const bin=(v,n)=>v===null?'?'.repeat(n):v.toString(2).padStart(n,'0');
 let s,render;
 const saved=window.openai?.widgetState?.privateContent;
 const save=()=>window.openai?.setWidgetState({modelContent:{topic:kind,...s},privateContent:s}).catch(()=>{});
 const commit=()=>{render();save();};
 if(kind==='register-lab'){
   s={mode:'level',d:0,q:0,ca:0,cb:0,clk:0,clear:1,...saved};
   root.innerHTML='<div class="lab-controls"><label>结构<select data-mode><option value="level">两组透明锁存 · 初态0000</option><option value="edge">四位上升沿寄存器 · 初态0000</option></select></label></div><div class="lab-buttons">'+[3,2,1,0].map(i=>`<button type="button" data-bit="${i}">D${i}=0</button>`).join('')+'</div><div class="lab-buttons" data-level><button type="button" data-ca>CLK_A=0</button><button type="button" data-cb>CLK_B=0</button></div><div class="lab-buttons" data-edge hidden><button type="button" data-clk>CLK=0</button><button type="button" data-clear>复位R_D′=1</button></div><svg role="img" aria-label="四个D存储单元的并行输入、时钟控制与输出"></svg><div class="lab-status" aria-live="polite"></div>';
   const svg=root.querySelector('svg');
   function settle(edge=false){if(s.mode==='edge'){if(s.clear===0)s.q=0;else if(edge)s.q=s.d;}else{const mask=(s.ca?3:0)|(s.cb?12:0);s.q=(s.q&(~mask&15))|(s.d&mask);}}
   render=()=>{const w=svg.clientWidth||320,x=w/2-42,edge=s.mode==='edge';let o='<title>四位寄存器</title><desc>每个方框存一位，D0与D1共用CLK_A，D2与D3共用CLK_B；或者四位统一采用上升沿时钟和低有效异步清零。模型初态0000，忽略延迟。</desc>'+text(w/2,21,'输入 '+bin(s.d,4)+' · 已存 '+bin(s.q,4),'middle');
     for(let i=0;i<4;i++){const y=48+i*108,d=(s.d>>i)&1,q=(s.q>>i)&1,c=edge?s.clk:i<2?s.ca:s.cb;o+=box(x,y,84,83)+text(8,y+12,'D'+i+'='+d)+line(`M 8 ${y+22} H ${x}`,!!d)+text(x+9,y+26,'1D')+text(8,y+44,(edge?'CLK':'CLK_'+(i<2?'A':'B'))+'='+c)+line(`M 8 ${y+54} H ${x}`,!!c)+text(x+(edge?19:9),y+58,'C1');if(edge)o+=line(`M ${x} ${y+47} L ${x+10} ${y+54} L ${x} ${y+61}`)+text(8,y+70,'R_D′='+s.clear)+line(`M 8 ${y+76} H ${x-8}`,!!s.clear)+bubble(x-4,y+76)+text(x+9,y+80,'R');o+=line(`M ${x+84} ${y+22} H ${w-8}`,!!q)+text(w-8,y+12,'Q'+i+'='+q,'end');}
     svg.setAttribute('viewBox',`0 0 ${w} 489`);svg.innerHTML=o;svg.dataset.q=s.q;svg.dataset.d=s.d;root.querySelector('[data-mode]').value=s.mode;root.querySelector('[data-level]').hidden=edge;root.querySelector('[data-edge]').hidden=!edge;
     root.querySelectorAll('[data-bit]').forEach(b=>{const i=+b.dataset.bit,v=(s.d>>i)&1;b.textContent='D'+i+'='+v;b.setAttribute('aria-pressed',!!v);});for(const k of ['ca','cb','clk','clear']){const b=root.querySelector('[data-'+k+']');b.textContent=({ca:'CLK_A',cb:'CLK_B',clk:'CLK',clear:'复位R_D′'}[k])+'='+s[k];b.setAttribute('aria-pressed',s[k]===1);}
     root.querySelector('.lab-status').textContent=edge?(s.clear===0?'异步清零有效':s.clk?'CLK保持高电平，D再变也不装入':'等待下一个上升沿'):'A组控制低两位，B组控制高两位；开放组持续跟随D';};
   root.querySelector('[data-mode]').onchange=e=>{s={mode:e.target.value,d:0,q:0,ca:0,cb:0,clk:0,clear:1};commit();};root.querySelectorAll('[data-bit]').forEach(b=>b.onclick=()=>{s.d^=1<<+b.dataset.bit;settle();commit();});for(const k of ['ca','cb','clk','clear'])root.querySelector('[data-'+k+']').onclick=()=>{const old=s.clk;s[k]^=1;settle(k==='clk'&&old===0&&s.clk===1);commit();};settle();
 }else if(kind==='ram-lab'){
   s={address:0,data:0,enabled:true,mode:'read',mem:Array(16).fill(null),...saved};if(!Array.isArray(s.mem)||s.mem.length!==16)s.mem=Array(16).fill(null);
   root.innerHTML='<div class="lab-controls"><label>地址 0—15<input data-address type="number" min="0" max="15" value="0"></label><label>控制<select data-mode><option value="read">读 · R/W′=1</option><option value="write">写 · R/W′=0</option></select></label><label>输入数据 0—15<input data-data type="number" min="0" max="15" value="0"></label></div><div class="lab-buttons"><label class="check"><input data-enabled type="checkbox" checked>片选有效 CS′=0</label><button type="button" data-write>执行一次写入</button></div><svg role="img" aria-label="16地址每字4位的RAM读写教学模型"></svg><div class="lab-status" aria-live="polite"></div>';
   const svg=root.querySelector('svg');render=()=>{const w=svg.clientWidth||320,cw=(w-16)/4;let o='<title>16×4 RAM读写</title><desc>每个格子是一个四位字，不是一个位。初始内容未知。只有片选有效并执行写操作才修改指定地址，读不会修改数据。</desc>'+text(w/2,19,'16个字 × 每字4位','middle')+text(w/2,43,'选中 '+bin(s.address,4)+' · CS′='+(s.enabled?0:1),'middle');for(let a=0;a<16;a++){const x=8+(a%4)*cw,y=64+Math.floor(a/4)*72,on=s.enabled&&a===s.address;o+=box(x,y,cw-6,59,on)+text(x+(cw-6)/2,y+21,'地址 '+a,'middle')+text(x+(cw-6)/2,y+43,bin(s.mem[a],4),'middle');}const value=!s.enabled?'Z Z Z Z':s.mode==='write'?'外部送入 '+bin(s.data,4):bin(s.mem[s.address],4);o+=text(w/2,382,'I/O：'+value,'middle');svg.setAttribute('viewBox',`0 0 ${w} 405`);svg.innerHTML=o;svg.dataset.mem=JSON.stringify(s.mem);svg.dataset.output=value;
     root.querySelector('[data-address]').value=s.address;root.querySelector('[data-data]').value=s.data;root.querySelector('[data-mode]').value=s.mode;root.querySelector('[data-enabled]').checked=s.enabled;root.querySelector('[data-write]').disabled=!(s.enabled&&s.mode==='write');root.querySelector('.lab-status').textContent=!s.enabled?'芯片未选中：不执行正常读写，输出高阻':s.mode==='read'?'RAM → 外部；读后该地址内容不变':'外部 → RAM；按钮代表一次满足时序的写操作';};
   for(const k of ['address','data'])root.querySelector('[data-'+k+']').onchange=e=>{s[k]=Math.max(0,Math.min(15,Math.floor(+e.target.value||0)));commit();};root.querySelector('[data-mode]').onchange=e=>{s.mode=e.target.value;commit();};root.querySelector('[data-enabled]').onchange=e=>{s.enabled=e.target.checked;commit();};root.querySelector('[data-write]').onclick=()=>{if(s.enabled&&s.mode==='write'){s.mem[s.address]=s.data;commit();}};
 }else if(kind==='expansion-lab'){
   const defs={word:{title:'4片256×8 → 1024×8',depth:256,max:1023},bit:{title:'4片1024×2 → 1024×8',depth:1024,max:1023},both:{title:'4片256×4 → 512×8',depth:256,max:511}};
   s={mode:'word',address:0,...saved};if(!defs[s.mode])s.mode='word';root.innerHTML='<div class="lab-controls"><label>扩展方式<select data-mode><option value="word">字扩展：高位选片</option><option value="bit">位扩展：共同工作拼宽</option><option value="both">混合扩展：两组，每组两片</option></select></label></div><label class="range-label">系统地址 <span data-value></span><input type="range" min="0" max="1023" value="0" data-address></label><svg role="img" aria-label="存储器扩展中的选片、片内地址与数据位分工"></svg><div class="lab-status" aria-live="polite"></div>';
   const svg=root.querySelector('svg');render=()=>{const c=defs[s.mode];s.address=Math.min(c.max,s.address);const w=svg.clientWidth||320,x=90,bw=w-153,bank=s.mode==='bit'?0:Math.floor(s.address/c.depth),offset=s.address%c.depth,sel=[];let o='<title>容量扩展</title><desc>每个方框代表一片芯片。左侧标注低有效片选，框内标注片内地址，右侧是该片承担的数据位。字扩展共享数据总线但只能一片选中；位扩展同时选中各片而各自提供不同数据位；混合扩展一次选中同组两片。</desc>'+text(w/2,20,c.title,'middle')+text(w/2,44,'片内地址 '+offset+' · 选中组 '+bank,'middle');
     for(let i=0;i<4;i++){const y=68+i*92,on=s.mode==='bit'||(s.mode==='word'?i===bank:Math.floor(i/2)===bank),hi=s.mode==='word'?7:s.mode==='bit'?i*2+1:(i%2)*4+3,lo=s.mode==='word'?0:s.mode==='bit'?i*2:(i%2)*4;sel.push(on);o+=box(x,y,bw,71,on)+text(8,y+25,'CS′='+(on?0:1))+line(`M 8 ${y+36} H ${x-8}`,on)+bubble(x-4,y+36)+text(x+bw/2,y+23,'芯片 '+i,'middle')+text(x+bw/2,y+46,'A片内='+offset,'middle')+line(`M ${x+bw} ${y+36} H ${w-8}`,on,!on)+text(w-8,y+25,'D'+hi+'…'+lo,'end');}
     o+=text(w/2,469,s.mode==='word'?'同名数据位并接；仅选中片驱动':s.mode==='bit'?'四片同选中；各自提供不同两位':'每组两片拼成8位；高位选一组','middle');svg.setAttribute('viewBox',`0 0 ${w} 491`);svg.innerHTML=o;Object.assign(svg.dataset,{selected:JSON.stringify(sel),bank,offset});root.querySelector('[data-mode]').value=s.mode;root.querySelector('[data-address]').max=c.max;root.querySelector('[data-address]').value=s.address;root.querySelector('[data-value]').textContent=s.address+' / 0x'+s.address.toString(16).toUpperCase();root.querySelector('.lab-status').textContent=s.mode==='word'?'高2位经译码生成互斥片选，低8位同接片内地址':s.mode==='bit'?'10位地址和控制同接，数据位分开':'高1位选组，低8位同接，同组两片分别提供高低4位';};
   root.querySelector('[data-mode]').onchange=e=>{s.mode=e.target.value;s.address=0;commit();};root.querySelector('[data-address]').oninput=e=>{s.address=+e.target.value;commit();};
 }else if(kind==='rom-lab'){
   const sets=[[2,3,6,7],[6,7,10,14],[4,14],[2,15]],display=['11111101','01100001','11011011','11110011','01100111','10110111','10111111','11100001','11111111','11110111','11111010','00111110','00011010','01111010','11011110','10001110'];
   s={mode:'functions',address:0,...saved};root.innerHTML='<div class="lab-controls"><label>课本例子<select data-mode><option value="functions">例5.5.2 · 四个逻辑函数</option><option value="display">例5.5.1 · 八段指定字形</option></select></label></div><label class="range-label">输入地址 <span data-value></span><input type="range" min="0" max="15" value="0" data-address></label><svg role="img" aria-label="ROM的地址数据矩阵及选中地址输出"></svg><div class="lab-status" aria-live="polite"></div>';
   const svg=root.querySelector('svg');render=()=>{const isDisplay=s.mode==='display',table=isDisplay?display:Array.from({length:16},(_,a)=>sets.map(set=>set.includes(a)?1:0).join('')),names=isDisplay?'abcdefgh'.split(''):['Y₁','Y₂','Y₃','Y₄'],w=svg.clientWidth||320,left=74,cw=(w-left-12)/names.length;let o='<title>ROM地址—数据表</title><desc>每行对应一个地址，每列对应一个输出数据位。实点表示该数据位为1，空圈为0。图是逻辑数据矩阵约定，不直接规定实物二极管的有无。显示例按课本指定字形和小数点数据。</desc>'+text(8,21,isDisplay?'DCBA':'ABCD');names.forEach((n,i)=>o+=text(left+(i+.5)*cw,21,n,'middle'));
     for(let a=0;a<16;a++){const y=42+a*23;if(a===s.address)o+=`<rect x="4" y="${y-14}" width="${w-8}" height="22" fill="var(--accent)"/>`;o+=text(8,y,bin(a,4));table[a].split('').forEach((v,i)=>o+=`<circle cx="${left+(i+.5)*cw}" cy="${y-4}" r="4" fill="${v==='1'?'var(--primary)':'none'}" stroke="${v==='1'?'var(--primary)':'var(--border)'}" stroke-width="1.2"/>`);}
     const out=table[s.address];o+=text(w/2,439,'输出 '+out,'middle');let h=468;
     if(isDisplay){const cx=w/2-27,cy=470,seg=[[[cx,cy],[cx+54,cy]],[[cx+59,cy+5],[cx+59,cy+45]],[[cx+59,cy+55],[cx+59,cy+95]],[[cx,cy+100],[cx+54,cy+100]],[[cx-5,cy+55],[cx-5,cy+95]],[[cx-5,cy+5],[cx-5,cy+45]],[[cx,cy+50],[cx+54,cy+50]]];seg.forEach((p,i)=>{o+=`<path d="M ${p[0][0]} ${p[0][1]} L ${p[1][0]} ${p[1][1]}" fill="none" stroke="${out[i]==='1'?'var(--primary)':'var(--border)'}" stroke-width="7" stroke-linecap="round"/>`;});o+=`<circle cx="${cx+79}" cy="${cy+99}" r="5" fill="${out[7]==='1'?'var(--primary)':'var(--border)'}"/>`;h=594;}
     svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=o;svg.dataset.output=out;svg.dataset.table=JSON.stringify(table);root.querySelector('[data-mode]').value=s.mode;root.querySelector('[data-address]').value=s.address;root.querySelector('[data-value]').textContent=bin(s.address,4)+'（'+s.address+'）';root.querySelector('.lab-status').textContent=isDisplay?'按教材指定字形，h是小数点；1表示段点亮':'D₃D₂D₁D₀依次接Y₁Y₂Y₃Y₄；按输出次序存一整行';};
   root.querySelector('[data-mode]').onchange=e=>{s.mode=e.target.value;s.address=0;commit();};root.querySelector('[data-address]').oninput=e=>{s.address=+e.target.value;commit();};
 }
 if(render){new ResizeObserver(render).observe(root);render();}
})();
